"""CPU-only R6 budget checks. Caller holds the single controller writer lock.

No Store permission, submission, settlement or budget refund occurs here.
Reservations remain charged even when an attempt or worker fails.
"""
import copy
import math


class BudgetError(ValueError):
    pass


def amount(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError('Resource amount must be numeric')
    if not math.isfinite(value) or value < 0:
        raise BudgetError('Resource amount must be finite and nonnegative')
    return value


def charged(reservation, caps):
    """Conservative charge: max(reserved, every pinned observation), never sum twice."""
    result = {}
    for resources in [reservation['resources'], *[o['resources'] for o in reservation.get('observations', [])]]:
        for resource, value in resources.items():
            if resource not in caps:
                raise BudgetError('Unknown resource: ' + resource)
            result[resource] = max(result.get(resource, 0), amount(value))
    return result


def totals(ledger, *, enforce_caps=True):
    caps = ledger['caps']
    result = {k: amount(ledger['used'][k]) for k in caps}
    seen = set()
    for reservation in ledger['reservations']:
        key = reservation['event_key']
        if key in seen:
            raise BudgetError('Duplicate reservation event')
        seen.add(key)
        for resource, value in charged(reservation, caps).items():
            result[resource] += value
    for resource, value in result.items():
        if enforce_caps and value > amount(caps[resource]):
            raise BudgetError('Cap exceeded: ' + resource)
    return result


def admissible(ledger):
    """Current hard and protected limits; also required before a first dispatch."""
    usage = totals(ledger)
    for resource, protected in ledger['protected_confirmation_delivery_repair'].items():
        # Protected use cannot accidentally become available to exploration.
        dev_used = amount(ledger['used'][resource])
        dev_used += sum(charged(r, ledger['caps']).get(resource, 0) for r in ledger['reservations']
                        if r['purpose'] == 'development')
        if dev_used > ledger['caps'][resource] - amount(protected):
            raise BudgetError('Protected capacity: ' + resource)
    model_cap = ledger['caps']['automatic_model_sessions']
    other_models = amount(ledger['used']['automatic_model_sessions']) + sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                       for r in ledger['reservations']
                       if r['purpose'] not in {'repair', 'final_review'})
    if other_models > model_cap - sum(ledger['protected_model_sessions'].values()):
        raise BudgetError('Protected review/repair sessions')
    for protected_role, count in ledger['protected_model_sessions'].items():
        outside_role = amount(ledger['used']['automatic_model_sessions'])
        outside_role += sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                            for r in ledger['reservations']
                            if r['purpose'] != protected_role)
        if outside_role > model_cap - count:
            raise BudgetError('Protected model role: ' + protected_role)
    return usage


def reserve(ledger, *, event_key, resources, purpose, free_disk_bytes):
    """Return a new ledger; identical replays don't spend again, drift fails.

    event_key binds goal, event, job, input hash and role. Final/recovery use
    of protected capacity is explicit. Ordinary development cannot borrow it.
    Disk check subtracts all outstanding output reservations conservatively.
    """
    required = {'goal_id', 'event_id', 'job_id', 'input_sha256', 'role'}
    if set(event_key) != required or event_key['goal_id'] != ledger['goal_id']:
        raise BudgetError('Incomplete event identity')
    if not all(isinstance(v, str) and v for v in event_key.values()):
        raise BudgetError('Empty event identity')
    digest = event_key['input_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise BudgetError('Invalid input hash')
    if purpose not in {'development', 'confirmation_delivery', 'repair', 'final_review'}:
        raise BudgetError('Unknown reservation purpose')
    key = tuple(event_key[k] for k in sorted(required))
    # JSON round trips preserve this stable string; tuples are not persisted.
    import json
    key = json.dumps(key, separators=(',', ':'))
    entry = {'event_key': key, 'identity': event_key, 'resources': resources, 'purpose': purpose}
    for prior in ledger['reservations']:
        if prior['event_key'] == key:
            if {k: prior[k] for k in entry} != entry:
                raise BudgetError('Reservation replay drift')
            admissible(ledger)
            return copy.deepcopy(ledger)
    candidate = copy.deepcopy(ledger)
    candidate['reservations'].append(copy.deepcopy(entry))
    usage = admissible(candidate)
    disk_key = 'output_actual_plus_unreleased_reservations_bytes'
    if amount(free_disk_bytes) - usage[disk_key] < ledger['disk_free_floor_bytes']:
        raise BudgetError('Disk floor after reservations')
    return candidate


def observe(ledger, *, event_key, resources, evidence):
    """Record pinned actuals, including overruns; never mutate/refund reservations.

    Actual cap breaches must be durable even though further reserve() will fail.
    Caller verifies evidence bytes and atomically saves this result with its event.
    """
    if (not isinstance(evidence, dict) or set(evidence) != {'path', 'sha256'}
            or not isinstance(evidence['path'], str) or not evidence['path']
            or not isinstance(evidence['sha256'], str) or len(evidence['sha256']) != 64
            or any(c not in '0123456789abcdef' for c in evidence['sha256'])):
        raise BudgetError('Observation evidence pin')
    if not isinstance(resources, dict) or not resources:
        raise BudgetError('Observation resources required')
    charged({'resources': resources}, ledger['caps'])
    result = copy.deepcopy(ledger)
    entries = [r for r in result['reservations'] if r['identity'] == event_key]
    if len(entries) != 1:
        raise BudgetError('Observation requires one exact reservation')
    observations = entries[0].setdefault('observations', [])
    new = {'resources': copy.deepcopy(resources), 'evidence': copy.deepcopy(evidence)}
    for old in observations:
        if old['evidence'] == evidence:
            if old != new:
                raise BudgetError('Observation replay drift')
            return result
    observations.append(new)
    usage = totals(result, enforce_caps=False)
    result['observed_cap_excess'] = {k: v-result['caps'][k] for k, v in usage.items() if v > result['caps'][k]}
    return result
"""First baseline: registered review -> exact issuance -> existing job runner.

The issuance event is the durable handoff. Once a submission claim exists, the
original runner owns recovery/STOP cleanup; no new review or approval is made.
"""
import argparse
import json
from pathlib import Path
import shutil

from rlflow.store import sha
from tools.r6_recovery import Journal, checked, RecoveryError
from tools.r6_batch import model_handoff
from tools.r6_job_handoff import no_model_workers
from tools.r6_postrun import stop_paths
from tools.r6_run_job import run as run_job
from tools import r6_initial_baseline as initial

ROLE = 'initial-baseline-authorization'


def require(condition, reason):
    if not condition:
        raise RecoveryError('START_BASELINE_'+reason)


def start(journal, plan_pin, master_pin, review_executable, store, *, free_disk_bytes):
    journal.require_writer()
    state = journal.read()
    edges = [(k, e) for k, e in state['events'].items() if e['identity']['role'] == ROLE]
    require(len(edges) <= 1, 'ISSUANCE_ALIAS')
    if edges:
        request = edges[0][1]['request']
        require(request['plan'] == plan_pin and request['master'] == master_pin
            and request['store_root'] == str(store.root.resolve()), 'ISSUANCE_DRIFT')
    if not edges or not edges[0][1].get('authorization_result'):
        active=initial.active_review(journal,plan_pin)
        reviews=[] if active is None else [(active,state['events'][active])]
        if reviews:
            key, review = reviews[0]
            require(review['request']['executable'] == review_executable, 'REVIEW_EXECUTABLE_DRIFT')
            if not review.get('dispatch_claim') and not review.get('receipt'):
                recovered = initial.register_review(journal, plan_pin, store,
                    executable=review_executable, free_disk_bytes=free_disk_bytes,
                    repair_pin=initial.repair_for_entry(journal,review,plan_pin))
                require(recovered == key, 'REVIEW_RECOVERY_DRIFT')
        else:
            key = initial.register_review(journal, plan_pin, store,
                executable=review_executable, free_disk_bytes=free_disk_bytes)
        model_handoff(journal, key)
        receipt = json.loads(checked(journal.read()['events'][key]['receipt']).read_text())
        result = initial.issue(journal, plan_pin, key, receipt['last_message'], master_pin,
            store, free_disk_bytes=free_disk_bytes)
        edges = [(result['event_key'], journal.read()['events'][result['event_key']])]
    edge_key, edge = edges[0]; request = edge['request']
    require(request['parent_key'] == 'INITIAL_BASELINE' and request['plan'] == plan_pin
        and request['master'] == master_pin and request['store_root'] == str(store.root.resolve()), 'ISSUANCE_DRIFT')
    state = journal.read(); review = state['events'][request['review_key']]
    require(review['request']['executable'] == review_executable, 'REVIEW_EXECUTABLE_DRIFT')
    plan = json.loads(checked(plan_pin).read_text())
    require(set(plan) == initial.FIELDS and plan['purpose'] == 'development'
        and plan['sandbox'] in {'read-only', 'danger-full-access'}, 'PLAN_FIELDS')
    spec = json.loads(checked(plan['spec_pin']).read_text())
    jid = 'J-'+sha({'id': spec['id'], 'spec': spec})[:16]
    expected = dict(goal_id=state['goal_id'], event_id='AUTHORIZE_NEXT:INITIAL_BASELINE',
                    job_id=jid, input_sha256=sha(request), role=ROLE)
    rows = [r for r in state['budget']['reservations'] if r['identity'] == expected]
    require(spec['id'] == initial.EXPERIMENT and edge['kind'] == 'cpu'
        and edge['identity'] == expected and sha(expected) == edge_key
        and edge['resources'] == {'output_actual_plus_unreleased_reservations_bytes': initial.CAP}
        and edge['purpose'] == 'development' and len(rows) == 1
        and rows[0]['resources'] == edge['resources'] and rows[0]['purpose'] == edge['purpose'], 'ISSUANCE_IDENTITY')
    issued = edge['authorization_result']
    require(issued['status'] == 'EXACT_INITIAL_BASELINE_AUTHORIZED_NOT_SUBMITTED'
        and issued['event_key'] == edge_key and issued['job_id'] == jid
        and issued['spec_sha256'] == sha(spec), 'ISSUANCE_RESULT')
    if edge.get('initial_job_result'):
        result = edge['initial_job_result']
        require(result['status'] == 'DECISION_PROPOSAL_RETURNED'
            and result['handoff_event_key'] == edge_key and result['scientific_acceptance'] is False,
            'CACHED_RESULT')
        require(journal.canonical_job(result['event_key'])['identity']['job_id'] == jid, 'CACHED_JOB')
        return result
    jobs = [e for e in state['events'].values() if e['kind'] == 'job' and e['identity']['job_id'] == jid]
    require(len(jobs) <= 1, 'JOB_ALIAS')
    if not jobs or not jobs[0].get('submission_claim'):
        journal.guard(); require(not stop_paths(journal), 'STOP'); no_model_workers(journal)
        require(state.get('current_job') is None and not any(
            e['kind'] == 'job' and e['identity']['job_id'] != jid for e in state['events'].values()),
            'OTHER_JOB')
        initial.delegation(journal, master_pin, store)
        initial.verify_review(journal, plan_pin, request['review_key'], request['review'], plan, jid)
    outcome = run_job(journal, store=store, free_disk_bytes=free_disk_bytes, **plan)
    require(outcome['status'] in {'RESOURCE_OBSERVATION_REJECTED', 'DECISION_PROPOSAL_RETURNED'}, 'RUNNER_STATUS')
    result = dict(status=outcome['status'], handoff_event_key=edge_key,
                  event_key=outcome.get('event_key'), scientific_acceptance=False)
    if result['status'] == 'DECISION_PROPOSAL_RETURNED':
        require(journal.canonical_job(result['event_key'])['identity']['job_id'] == jid, 'RUNNER_JOB')
        state = journal.read(); state['events'][edge_key]['initial_job_result'] = result; journal.save(state)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory', type=Path); parser.add_argument('request', type=Path)
    parser.add_argument('--request-sha256', required=True); parser.add_argument('--store', type=Path, required=True)
    args = parser.parse_args()
    request = json.loads(checked(dict(path=str(args.request.resolve()), sha256=args.request_sha256)).read_text())
    require(set(request) == {'plan_pin', 'master_pin', 'review_executable'}, 'REQUEST_FIELDS')
    root = args.store.resolve(strict=True); require((root/'runtime/research.db').is_file(), 'STORE_REQUIRED')
    from rlflow.store import Store
    journal = Journal(args.directory.resolve())
    with journal.writer():
        result = start(journal, store=Store(root), free_disk_bytes=shutil.disk_usage(journal.directory).free, **request)
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    main()
